import * as T from './vendor/three.module.js';
import {experienceSpec,CINEMA_SHORTS} from './engine.js?v=66.0.0';
import {paintCinemaArt,cinemaPalette} from './cinema-art.js?v=63.0.0';
import {detailBoxes} from './detail-instances.js?v=48.0.0';
export function buildCinemaDetails(w,v){const root=new T.Group();root.position.set(v.x+v.width/2,0,v.y+v.height/2);w.scene.add(root);const W=v.width,D=v.height,parts=[],box=(...a)=>parts.push(a),wood='#71634f',fabric='#9d6f60',ink='#3c5c61',paper='#e6dcc2';box(0,2,0,W-2,4,D-2,ink);box(0,35,-D/2+3,W-6,66,4,wood);box(0,43,-D/2+6,W-12,46,2,ink);box(0,69,-D/2+5,W-10,2,8,paper);
 for(let row=0;row<2;row++)for(let col=0;col<3;col++){const x=(col-1)*28,z=-2+row*25;box(x,11,z,20,6,17,fabric);box(x,23,z+6,20,24,4,fabric);box(x,23,z+8.4,16,19,.6,'#b28a74');for(const dx of[-10,10]){box(x+dx,13,z,2,24,3,wood);box(x+dx,21,z,3,3,14,paper);}for(const dx of[-6,6])box(x+dx,5,z+1,2,8,12,ink);const cup=w.mesh(new T.TorusGeometry(1.1,.3,5,12),w.mat(ink),root);cup.rotation.x=Math.PI/2;cup.position.set(x+10,23,z-4);}
 box(0,13,D/2-6,32,26,10,wood);box(0,27,D/2-6,35,2,11,paper);for(let i=0;i<4;i++)box(-6+i*4,28.2,D/2-6,3,.3,6,i%2?'#ba8d65':paper);for(const sign of[-1,1]){const post=w.mesh(new T.CylinderGeometry(1,1,28,10),w.mat('#a5a899',{metalness:.5}),root);post.position.set(sign*(W/2-5),16,D/2-5);box(sign*(W/2-5),3,D/2-5,6,2,6,wood);}box(0,27,D/2-5,W-12,1,1,ink);
 const canvases=[],textures=[],makeTexture=()=>{if(!globalThis.document?.createElement)return null;const c=document.createElement('canvas');c.width=1024;c.height=640;if(!c.getContext?.('2d'))return null;const tx=new T.CanvasTexture(c);tx.colorSpace=T.SRGBColorSpace;w.resources.add(tx);canvases.push(c);textures.push(tx);return tx;},screen=w.mesh(new T.PlaneGeometry(W-20,38),w.mat(paper,{map:makeTexture(),roughness:.9}),root);screen.position.set(0,43,-D/2+7.2);
 for(const sign of[-1,1]){const frame=w.mesh(new T.BoxGeometry(2,34,25),w.mat(wood),root);frame.position.set(sign*(W/2-3),43,-D/2+25);const poster=w.mesh(new T.PlaneGeometry(21,29),w.mat(paper,{map:makeTexture(),roughness:.9}),root);poster.position.set(sign*(W/2-4.1),43,-D/2+25);poster.rotation.y=-sign*Math.PI/2;}
 const marker=w.mesh(new T.BoxGeometry(20,2,.4),w.mat('#8ab496'),root);marker.position.set(0,19,D/2-.6);marker.visible=false;detailBoxes(w,root,parts);w.cinemaDisplay={root,canvases,textures,marker,signature:null};w.canvas.dataset.cinemaRevision='63';updateCinemaDetails(w);return root;}
export function updateCinemaDetails(w){const d=w.cinemaDisplay;if(!d)return;const a=experienceSpec(w.state,'cinema'),playing=w.action?.kind==='cinema',elapsed=playing?(performance.now()-w.action.startTime)/1000:0,scene=playing?(w.state.preferences.reducedMotion?2:Math.min(2,Math.floor(Math.max(0,elapsed)/1.6))):0,signature=[w.state.day,a.film.id,a.completed,scene].join(':');if(signature===d.signature)return;d.signature=signature;d.marker.visible=a.completed;
 for(const[i,c]of d.canvases.entries()){const film=i===0?a.film:CINEMA_SHORTS[(CINEMA_SHORTS.findIndex(f=>f.id===a.film.id)+i)%CINEMA_SHORTS.length],ctx=c.getContext('2d'),colors=cinemaPalette(film.id);ctx.fillStyle='#eee5cf';ctx.fillRect(0,0,c.width,c.height);ctx.save();ctx.translate(40,110);paintCinemaArt(ctx,film.id,i===0?scene:0,944,440);ctx.restore();ctx.fillStyle=colors[2];ctx.textAlign='center';ctx.font='600 47px Georgia';ctx.fillText(film.title,512,68,960);ctx.font='27px Arial';ctx.fillText(i===0?'DAY '+w.state.day+' · ORIGINAL MALLSIDE SHORT'+(a.completed?' · MEMORY SAVED':''):'ORIGINAL POSTER COLLECTION',512,606,960);d.textures[i].needsUpdate=true;}
 w.canvas.dataset.cinemaFilm=a.film.id;w.canvas.dataset.cinemaScene=String(scene);w.canvas.dataset.cinemaCompleted=String(a.completed);}
